output.text:
 35	      `Migration directory has no UTC timestamp: ${directoryName}`
 36	    );
 37	  }
 38	
 39	  return Date.UTC(
 40	    Number(datePart.slice(0, 4)),
 41	    Number(datePart.slice(4, 6)) - 1,
 42	    Number(datePart.slice(6, 8)),
 43	    Number(datePart.slice(8, 10)),
 44	    Number(datePart.slice(10, 12)),
 45	    Number(datePart.slice(12, 14))
 46	  );
 47	}
