 49	function readMigrations() {
 50	  if (!existsSync(migrationFolder)) {
 51	    throw new Error("Committed migrations are missing from this image.");
 52	  }
 53	
 54	  return readdirSync(migrationFolder)
 55	    .map((directoryName) => ({
 56	      directoryName,
 57	      path: join(migrationFolder, directoryName, MIGRATION_FILE_NAME),
 58	    }))
 59	    .filter((migration) => existsSync(migration.path))
 60	    .sort((left, right) =>
 61	      left.directoryName.localeCompare(right.directoryName)
 62	    )
 63	    .map(({ directoryName, path }) => {
 64	      const source = readFileSync(path, "utf8");
 65	
 66	      return {
 67	        createdAt: migrationTimestamp(directoryName),
 68	        hash: createHash("sha256").update(source).digest("hex"),
 69	        statements: source
 70	          .split(MIGRATION_STATEMENT_SEPARATOR)
 71	          .filter((statement) => statement.trim().length > 0),
 72	      };
 73	    });
 74	}
