 76	async function applyMigrations() {
 77	  const client = new pg.Client({ connectionString: requiredDatabaseUrl() });
 78	
 79	  try {
 80	    await client.connect();
 81	    await client.query(`CREATE SCHEMA IF NOT EXISTS ${MIGRATIONS_SCHEMA}`);
 82	    await client.query(`
 83	      CREATE TABLE IF NOT EXISTS ${MIGRATIONS_SCHEMA}.${MIGRATIONS_TABLE} (
 84	        id SERIAL PRIMARY KEY,
 85	        hash text NOT NULL,
 86	        created_at bigint
 87	      )
 88	    `);
 89	
 90	    const appliedResult = await client.query(
 91	      `SELECT created_at FROM ${MIGRATIONS_SCHEMA}.${MIGRATIONS_TABLE}`
 92	    );
 93	    const appliedCreatedAt = new Set(
 94	      appliedResult.rows.map((migration) => Number(migration.created_at))
 95	    );
 96	
 97	    for (const migration of readMigrations()) {
 98	      if (appliedCreatedAt.has(migration.createdAt)) {
 99	        continue;
100	      }
101	
102	      await client.query("BEGIN");
103	      try {
104	        for (const statement of migration.statements) {
105	          await client.query(statement);
106	        }
107	        await client.query(
108	          `INSERT INTO ${MIGRATIONS_SCHEMA}.${MIGRATIONS_TABLE} (hash, created_at) VALUES ($1, $2)`,
109	          [migration.hash, migration.createdAt]
110	        );
111	        await client.query("COMMIT");
112	      } catch (error) {
113	        await client.query("ROLLBACK");
114	        throw error;
115	      }
116	    }
117	  } finally {
118	    await client.end();
119	  }
120	}
